#include <stdio.h>
#include <stdint.h>

#define Q16_SHIFT 16
#define FLOAT_TO_Q16(x) ((int32_t)((x) * (1 << Q16_SHIFT)))

int main(void) {
    int32_t a = FLOAT_TO_Q16(2.5);
    int32_t b = FLOAT_TO_Q16(3.0);
    int32_t prod = (int32_t)(((int64_t)a * b) >> Q16_SHIFT);
    printf("%d\n", prod >> Q16_SHIFT);
    return 0;
}

